# -*- coding: utf-8 -*-
"""
主窗口模块。

负责构建应用程序的主界面，包含单词查询、单词抽查、设置以及数据操作四个标签页。
管理数据库、收藏文件、后台工作线程，并协调各业务处理器的调用。
"""

import os
from typing import Dict

from loguru import logger
from PySide6.QtCore import Qt
from PySide6.QtGui import QFont
from PySide6.QtWidgets import (
    QComboBox,
    QFileDialog,
    QGridLayout,
    QHBoxLayout,
    QLabel,
    QLineEdit,
    QListWidget,
    QMainWindow,
    QMenu,
    QMessageBox,
    QProgressBar,
    QPushButton,
    QSizePolicy,
    QStackedWidget,
    QTabWidget,
    QTextBrowser,
    QTextEdit,
    QVBoxLayout,
    QWidget,
)

from graphics.settings import get_settings_tab_widget
from handle.query_handle import QueryHandler
from handle.quiz_handle import QuizHandler
from utils.data_ops import (
    backup_database,
    check_database_status,
    delete_database,
    rebuild_favorites_from_db,
)
from utils.database import DatabaseManager
from utils.favorites import FavoritesManager
from utils.local_search import search_words
from utils.path import build_data_paths, get_timestamp
from utils.query_worker import QueryWorker
from utils.rebuild_worker import RebuildWorker
from utils.text import decode_base64, format_word_info


class MainWindow(QMainWindow):
    """
    应用程序主窗口类。

    包含四个标签页：
        - 单词查询：输入单词查询释义，并可收藏至本地列表。
        - 单词抽查：根据随机单词进行释义反向或正向练习。
        - 设置：加载用户偏好配置。
        - 数据操作：备份、删除、重建数据库和收藏文件。
    """

    ABOUT_BASE64_TOP = ""
    ABOUT_BASE64_BOTTOM = ""

    def __init__(self):
        """初始化主窗口，设置路径、数据库连接、UI 组件和业务处理器。"""
        super().__init__()

        # 从环境变量获取数据根目录，若不存在则回退到当前文件所在目录
        project_root = os.environ.get("WORDBOOK_DATA_ROOT", os.path.dirname(os.path.abspath(__file__)))
        self.paths = build_data_paths(project_root)
        self.db_path = self.paths.db_path
        self.favorites_path = self.paths.favorites_path
        self.backup_dir = self.paths.backup_dir
        self.help_path = self.paths.help_path

        self.setWindowTitle("WordBook - 单词本")
        self.resize(800, 600)

        self.db_manager = DatabaseManager(self.db_path)
        self.favorites_manager = FavoritesManager(self.favorites_path)

        # 核心控件：标签页容器
        self.tab_widget = QTabWidget()
        self.setCentralWidget(self.tab_widget)

        # 工作线程引用
        self.current_worker = None
        self.rebuild_worker = None
        self.current_query_word = ""

        # 抽查状态
        self.quiz_started = False
        self.original_quiz_info = ""

        # 本地检索状态
        self.local_search_mode = False

        # 业务处理器
        self.query_handler = QueryHandler()
        self.quiz_handler = QuizHandler()

        # 初始化标签页
        self.init_tab_query()
        self.init_tab_quiz()
        self.init_tab_settings()
        self.init_tab_data_operation()
        self.init_tab_about()
        self.init_tab_help()

        # 连接 Tab 切换信号，用于数据操作页实时刷新
        self.tab_widget.currentChanged.connect(self.on_tab_changed)

        # 加载收藏列表
        self.load_favorites()
        logger.debug("主窗口初始化完成")

    def init_tab_about(self):
        """初始化“关于”标签页，上下两个只读文本框显示 Base64 解码后的纯文本。"""
        tab = QWidget()
        layout = QVBoxLayout()

        self.about_top = QTextBrowser()
        self.about_top.setReadOnly(True)
        self.about_top.setOpenExternalLinks(True)
        self.about_top.setPlaceholderText("版权信息")
        self.about_bottom = QTextEdit()
        self.about_bottom.setReadOnly(True)
        self.about_bottom.setPlaceholderText("开源协议")

        self.about_top.setMarkdown(decode_base64(self.ABOUT_BASE64_TOP))
        self.about_bottom.setPlainText(decode_base64(self.ABOUT_BASE64_BOTTOM))

        layout.addWidget(self.about_top, 1)
        layout.addWidget(self.about_bottom, 1)
        tab.setLayout(layout)
        self.tab_widget.addTab(tab, "关于")

    def init_tab_help(self):
        """初始化“帮助”标签页，从 data/graphics/help.md 读取并渲染 Markdown。"""
        tab = QWidget()
        layout = QVBoxLayout()
        self.help_text = QTextEdit()
        self.help_text.setReadOnly(True)
        self.help_text.setPlaceholderText("帮助内容未找到")

        try:
            if os.path.exists(self.help_path):
                with open(self.help_path, "r", encoding="utf-8") as f:
                    content = f.read()
                self.help_text.setMarkdown(content)
            else:
                self.help_text.setPlainText(f"帮助文件不存在：{self.help_path}")
        except Exception as e:
            logger.error(f"读取帮助文件失败：{e}")
            self.help_text.setPlainText(f"读取帮助文件失败：{e}")

        layout.addWidget(self.help_text)
        tab.setLayout(layout)
        self.tab_widget.addTab(tab, "帮助")

    def init_tab_query(self):
        """
        初始化“单词查询”标签页。

        布局：
            - 顶部：输入框和查询按钮。
            - 底部：左侧收藏单词列表，右侧详细信息显示区，以及收藏按钮。
        连接信号与槽。
        """
        tab1 = QWidget()
        layout = QVBoxLayout()

        # 顶部区域：输入框 + 查询按钮
        top_layout = QHBoxLayout()
        self.query_input = QLineEdit()
        self.query_input.returnPressed.connect(self.on_query)
        self.query_input.setPlaceholderText("输入单词...")
        self.query_btn = QPushButton("查询")
        self.local_search_btn = QPushButton("本地检索")
        top_layout.addWidget(self.query_input)
        top_layout.addWidget(self.query_btn)
        top_layout.addWidget(self.local_search_btn)

        # 底部区域：单词列表、信息区、操作按钮
        bottom_layout = QHBoxLayout()
        self.word_list = QListWidget()
        self.word_list.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.word_list.customContextMenuRequested.connect(self.show_context_menu)
        self.word_info = QTextEdit()
        self.word_info.setReadOnly(True)
        self.word_info.setPlaceholderText("单词详细信息将显示在这里...")
        self.action_btn = QPushButton("收藏")

        self.word_list.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Expanding)
        self.word_info.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Expanding)

        bottom_layout.addWidget(self.word_list, 1)
        bottom_layout.addWidget(self.word_info, 2)
        bottom_layout.addWidget(self.action_btn)

        layout.addLayout(top_layout)
        layout.addLayout(bottom_layout)
        tab1.setLayout(layout)

        # 信号连接
        self.query_btn.clicked.connect(self.on_query)
        self.local_search_btn.clicked.connect(self.on_toggle_local_search)
        self.action_btn.clicked.connect(self.on_add_to_list)
        self.word_list.itemClicked.connect(self.on_word_selected)

        self.tab_widget.addTab(tab1, "单词查询")

    def show_context_menu(self, pos):
        """
        显示单词列表的右键菜单，提供删除功能。

        Args:
            pos: 右键点击位置（相对坐标）。
        """
        item = self.word_list.itemAt(pos)
        if not item:
            return

        menu = QMenu(self)
        delete_action = menu.addAction("删除此单词")
        action = menu.exec_(self.word_list.mapToGlobal(pos))

        if action == delete_action:
            self.delete_word(item.text())

    def delete_word(self, word: str):
        """
        从收藏文件中删除指定单词。

        Args:
            word: 要删除的单词字符串。
        """
        reply = QMessageBox.question(
            self,
            "确认删除",
            f"确定要从收藏列表中删除 '{word}' 吗？",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
        )
        if reply != QMessageBox.StandardButton.Yes:
            return

        try:
            if self.favorites_manager.delete(word):
                logger.info(f"单词 '{word}' 已从收藏列表删除")
                self.load_favorites()
        except Exception as e:
            logger.error(f"删除单词失败：{e}")
            QMessageBox.critical(self, "错误", f"删除失败：{e}")

