        db_group.setLayout(db_layout)

        # ---- 收藏操作区域 ----
        fav_group = QWidget()
        fav_layout = QGridLayout()
        fav_layout.addWidget(QLabel("收藏操作"), 0, 0, 1, 3)

        self.btn_fav_backup = QPushButton("备份收藏")
        self.btn_fav_backup.clicked.connect(self.on_fav_backup)
        fav_layout.addWidget(self.btn_fav_backup, 1, 0)

        self.btn_fav_delete = QPushButton("删除收藏")
        self.btn_fav_delete.clicked.connect(self.on_fav_delete)
        fav_layout.addWidget(self.btn_fav_delete, 1, 1)

        self.btn_fav_import = QPushButton("从文件导入")
        self.btn_fav_import.clicked.connect(self.on_fav_import)
        fav_layout.addWidget(self.btn_fav_import, 1, 2)

        self.btn_fav_rebuild = QPushButton("从数据库重建")
        self.btn_fav_rebuild.clicked.connect(self.on_fav_rebuild)
        fav_layout.addWidget(self.btn_fav_rebuild, 1, 3)

        self.lbl_fav_status = QLabel("收藏：未检查")
