        fav_layout.addWidget(self.lbl_fav_status, 3, 0, 1, 3)

        fav_group.setLayout(fav_layout)

        layout.addWidget(db_group)
        layout.addWidget(fav_group)
        layout.addStretch()
        tab4.setLayout(layout)

        self.tab_widget.addTab(tab4, "数据操作")
